import React, { useEffect, useRef, useState } from "react";
import * as faceapi from "face-api.js";
import '../App.css';
import SuccessDance from '../Image/MicDance.gif'
import SadDance from '../Image/MicSad.gif'
import MicRun from '../Image/MicRun.gif'

const Home = () => {
    const [referenceImage, setReferenceImage] = useState(null);
    const [result, setResult] = useState("No results");
    const [modelsLoaded, setModelsLoaded] = useState(false);
    const canvasRef = useRef(null);
    const videoRef = useRef(null);
    const [webcamActive, setWebcamActive] = useState(false);
    const [buttonClicked, setButtonClicked] = useState(false);
    const [animationClass, setAnimationClass] = useState("");
    const [loading, setLoading] = useState(false);
    const [resultBackgroundColor, setResultBackgroundColor] = useState('#f8f9fa');

    useEffect(() => {
        const loadModels = async () => {
            //const PulicUrl = "http://localhost:3000/FaceRecognition";
            const PulicUrl = process.env.PUBLIC_URL || "";  
            setLoading(true);
            try {
                await Promise.all([
                    faceapi.nets.ssdMobilenetv1.loadFromUri(PulicUrl + "/models"),
                    faceapi.nets.faceLandmark68Net.loadFromUri(PulicUrl + "/models"),
                    faceapi.nets.faceRecognitionNet.loadFromUri(PulicUrl + "/models"),
                    faceapi.nets.ageGenderNet.loadFromUri(PulicUrl + "/models"),
                    faceapi.nets.faceExpressionNet.loadFromUri(PulicUrl + "/models"),
                ]);
                setModelsLoaded(true);
            } catch (error) {
                console.error("Error loading models:", error);
                alert("Failed to load models. Check console for details.");
            } finally {
                setLoading(false);
            }
        };

        loadModels();
    }, []);

    const handleReferenceImageChange = (event) => {
        const file = event.target.files[0];
        if (file) {
            const imageUrl = URL.createObjectURL(file);
            setReferenceImage(imageUrl);
        }
    };

    const startWebcam = async () => {
        setWebcamActive(true);
        setAnimationClass("animate-center");
        try {
            const stream = await navigator.mediaDevices.getUserMedia({ video: true });
            videoRef.current.srcObject = stream;

            videoRef.current.onloadedmetadata = () => {
                videoRef.current.play().catch((error) => {
                    console.error("Error trying to play the video:", error);
                });
            };

            setTimeout(() => {
                setAnimationClass("");
            }, 500);
        } catch (error) {
            console.error('Error accessing webcam:', error);
            alert('Could not access webcam. Please check your permissions.');
        }
    };

    const stopWebcam = () => {
        if (videoRef.current && videoRef.current.srcObject) {
            const stream = videoRef.current.srcObject;
            const tracks = stream.getTracks();
            tracks.forEach(track => track.stop());
            setWebcamActive(false);
            setButtonClicked(false);
        }
    };

    const recognizeFaces = async () => {
        setButtonClicked(true);
        setLoading(true); // Start processing
    
        if (!modelsLoaded) {
            alert("Models are still loading. Please wait.");
            setLoading(false); // Stop processing
            return;
        }
    
        if (referenceImage) {
            const referenceImg = await faceapi.fetchImage(referenceImage);
            const referenceDetect = await faceapi.detectAllFaces(referenceImg).withFaceLandmarks().withFaceDescriptors();
            const referenceDescriptors = referenceDetect.map(d => d.descriptor);
    
            const intervalId = setInterval(async () => {
                const video = videoRef.current;
                const targetDetect = await faceapi.detectAllFaces(video)
                    .withFaceLandmarks()
                    .withFaceDescriptors()
                    .withAgeAndGender()
                    .withFaceExpressions();
    
                if (targetDetect.length > 0) {
                    const targetDescriptors = targetDetect.map(d => d.descriptor);
                    const faceMatcher = new faceapi.FaceMatcher(referenceDescriptors);
                    const matchResults = targetDescriptors.map(descriptor => {
                        const bestMatch = faceMatcher.findBestMatch(descriptor);
                        return { label: bestMatch.label, confidence: bestMatch.distance };
                    });
    
                    const confidenceThreshold = 0.6;
                    const matchedFacesSet = new Set();
                    const matchedFacesArray = [];
    
                    matchResults.forEach((result, index) => {
                        if (result.confidence < confidenceThreshold) {
                            if (!matchedFacesSet.has(result.label)) {
                                matchedFacesSet.add(result.label);
                                matchedFacesArray.push({
                                    label: result.label,
                                    detection: targetDetect[index],
                                    age: targetDetect[index].age,
                                    gender: targetDetect[index].gender,
                                    expressions: targetDetect[index].expressions,
                                });
                            }
                        }
                    });
    
                    const matchCount = matchedFacesArray.length;
    
                    if (matchCount > 0) {
                        const matchedFacesMessage = matchedFacesArray.map(face => `${face.label}`).join(", ");
                        setResult(`Matched Face(s): ${matchedFacesMessage} | Total Matches: ${matchCount} `);
                        setResultBackgroundColor('#d4edda'); // Green background for matches
                    } else {
                        setResult("No match found."); // Message for no matches
                        setResultBackgroundColor('#f8d7da'); // Red background for no matches
                    }
    
                    const canvas = canvasRef.current;
                    const displaySize = { width: video.videoWidth, height: video.videoHeight };
    
                    faceapi.matchDimensions(canvas, displaySize);
                    const resizedDetections = faceapi.resizeResults(targetDetect, displaySize);
    
                    const context = canvas.getContext("2d");
                    context.clearRect(0, 0, canvas.width, canvas.height);
    
                    resizedDetections.forEach((detection, index) => {
                        const { x, y, width, height } = detection.detection.box;
    
                        // Get matched face info
                        const matchedFace = matchedFacesArray.find(face => face.label === matchResults[index].label);
    
                        // Draw box only if it is matched (green) or unmatched (red)
                        context.strokeStyle = matchedFace ? "green" : "red";
                        context.lineWidth = matchedFace ? 3 : 2;
                        context.strokeRect(x, y, width, height);
    
                        // Display age, gender, and expression above the box
                        const ageText = `Age: ${Math.round(detection.age)}`;
                        const genderText = `Gender: ${detection.gender}`;
                        const expressionText = `Expression: ${Object.keys(detection.expressions).reduce((a, b) => detection.expressions[a] > detection.expressions[b] ? a : b)}`;
    
                        context.fillStyle = "white";
                        context.font = "15px Arial";
                        context.fillText(ageText, x, y > 10 ? y - 10 : 10);
                        context.fillText(genderText, x, y > 30 ? y - 30 : 30);
                        context.fillText(expressionText, x, y > 50 ? y - 50 : 50);
                    });
                } else {
                    setResult("Face(s) not detected."); // Message for no faces detected
                    setResultBackgroundColor('#f8d7da'); // Red background for no faces detected
                }
                setLoading(false); // Stop processing after results are handled
            }, 100);
    
            return () => clearInterval(intervalId);
        }
    };
    

    return (
        <>
            <h1 style={{ backgroundColor: '#5b446a', color: 'white', borderRadius: '10px', padding: '10px', fontSize: '24px' }}>Face Recognition App</h1>

            <div className="container col-xxl-8 px-4 py-5">
                <div className="image-container" style={{ marginBottom: '20px', backgroundColor: '#d3d6db', borderRadius: '10px', boxShadow: 'rgba(50, 50, 93, 0.25) 0px 2px 5px -1px, rgba(0, 0, 0, 0.3) 0px 1px 3px -1px' }}>
                    <input
                        type="file"
                        id="referenceImage"
                        accept="image/*"
                        className="custom-file-input p-2"
                        onChange={handleReferenceImageChange}
                    />
                    {referenceImage && <img src={referenceImage} alt="Reference" width="100%" className="m-4" style={{ maxWidth: '150px', marginTop: '10px', borderRadius: '5px', boxShadow: 'rgba(0, 0, 0, 0.16) 0px 3px 6px, rgba(0, 0, 0, 0.23) 0px 3px 6px' }} />}
                </div>

                <div className="row flex-lg-row-reverse align-items-center g-5 py-5">
                    <div className={`col-lg-6 position-relative ${animationClass}`}>
                        <video ref={videoRef} style={{ width: '100%', borderRadius: '10px' }} />
                        <canvas ref={canvasRef} style={{ position: "absolute", top: -23, left: 0, width: '100%', height: '100%', borderRadius: '10px' }} />
                    </div>

                    <div className="col-lg-6">
                        <h3 style={{ color: '#5b446a', borderBottom: '2px solid #5b446a', paddingBottom: '10px' }}>Results</h3>
                        <div className="result-box" style={{ backgroundColor: resultBackgroundColor, borderRadius: '10px', padding: '10px', marginBottom: '10px' }}>
    <p style={{ color: '#5b446a', fontWeight: 'bold', fontSize: '14px', textAlign: 'center' }}>
        {result.includes("Matched Face(s):") && (
            <img src={SuccessDance} alt="Match Found" style={{ width: '100px', height: '100px', display: 'block', margin: '0 auto' }} />
        )}
        {result.includes("No match found.") && (
            <img src={SadDance} alt="No Match" style={{ width: '100px', height: '100px', display: 'block', margin: '0 auto' }} />
        )}
        {result.includes("Face(s) not detected.") && (
            <img src={MicRun} alt="Face Not Detected" style={{ width: '100px', height: '100px', display: 'block', margin: '0 auto' }} />
        )}
        <span style={{ display: 'block', marginTop: '10px' }}>{result}</span>
    </p>
</div>



{!webcamActive ? (
    <button onClick={startWebcam} style={{backgroundColor:'#247291',color:'#f8da5b'}} className="btn ">
        Start Webcam
    </button>
) : (
    <>
        <button onClick={recognizeFaces} style={{backgroundColor:'#38598b'}} className="btn btn-success m-2" disabled={loading}>
            {loading ? "Processing..." : "Recognize Faces"} {/* Change button text based on loading state */}
        </button>
        <button onClick={stopWebcam} style={{backgroundColor:'#247291',color:'#f8da5b'}} className="btn btn-success m-2">
            Stop Webcam
        </button>
    </>
)}

                    </div>
                </div>
            </div>
        </>
    );
};

export default Home;
